import{MantaStatusCode}from"./sea_pen.mojom-webui.js";import*as seaPenAction from"./sea_pen_actions.js";import{isNonEmptyArray,isNonEmptyFilePath}from"./sea_pen_utils.js";export async function selectRecentSeaPenImage(image,provider,store){if(isNonEmptyFilePath(image)&&image.path===store.data.currentSelected){return}store.beginBatchUpdate();store.dispatch(seaPenAction.beginSelectRecentSeaPenImageAction(image));store.dispatch(seaPenAction.beginLoadSelectedRecentSeaPenImageAction());store.endBatchUpdate();const{success:success}=await provider.selectRecentSeaPenImage(image);store.beginBatchUpdate();store.dispatch(seaPenAction.endSelectRecentSeaPenImageAction(image,success));if(!success){console.warn("Error setting wallpaper")}store.endBatchUpdate()}export async function searchSeaPenThumbnails(query,provider,store){store.dispatch(seaPenAction.beginSearchSeaPenThumbnailsAction(query));const{images:images,statusCode:statusCode}=await provider.searchWallpaper(query);if(!isNonEmptyArray(images)||statusCode!==MantaStatusCode.kOk){console.warn("Error generating thumbnails. Status code: ",statusCode)}store.dispatch(seaPenAction.setThumbnailResponseStatusCodeAction(statusCode));store.dispatch(seaPenAction.setSeaPenThumbnailsAction(query,images))}export async function selectSeaPenWallpaper(thumbnail,provider,store){store.dispatch(seaPenAction.beginSelectSeaPenThumbnailAction(thumbnail));const{success:success}=await provider.selectSeaPenThumbnail(thumbnail.id);store.dispatch(seaPenAction.endSelectSeaPenThumbnailAction(thumbnail,success));if(store.data.loading.setImage===0){store.dispatch(seaPenAction.setSelectedRecentSeaPenImageAction(success?`${thumbnail.id}.jpg`:null))}if(success){await fetchRecentSeaPenData(provider,store)}}export async function clearSeaPenThumbnails(store){store.dispatch(seaPenAction.clearSeaPenThumbnailsAction())}export async function deleteRecentSeaPenImage(image,provider,store){const{success:success}=await provider.deleteRecentSeaPenImage(image);if(success){fetchRecentSeaPenData(provider,store)}}export async function getRecentSeaPenImages(provider,store){store.dispatch(seaPenAction.beginLoadRecentSeaPenImagesAction());const{images:images}=await provider.getRecentSeaPenImages();if(images==null){console.warn("Failed to fetch recent sea pen images")}store.dispatch(seaPenAction.setRecentSeaPenImagesAction(images))}export async function fetchRecentSeaPenData(provider,store){if(!store.data.loading.recentImages){await getRecentSeaPenImages(provider,store)}await getMissingRecentSeaPenImageData(provider,store)}const recentSeaPenImageDataToFetch=new Set;async function getMissingRecentSeaPenImageData(provider,store){if(!Array.isArray(store.data.recentImages)){console.warn("Cannot fetch thumbnails with invalid image list");return}store.beginBatchUpdate();for(const image of store.data.recentImages){if(store.data.recentImageData[image.path]||store.data.loading.recentImageData[image.path]||recentSeaPenImageDataToFetch.has(image.path)){continue}recentSeaPenImageDataToFetch.add(image.path);store.dispatch(seaPenAction.beginLoadRecentSeaPenImageDataAction(image))}store.endBatchUpdate();while(recentSeaPenImageDataToFetch.size){await Promise.all(Array.from(recentSeaPenImageDataToFetch).map((async path=>{recentSeaPenImageDataToFetch.delete(path);const{url:url}=await provider.getRecentSeaPenImageThumbnail({path:path});const queryInfo="query "+Math.floor(Math.random()*100+1).toString();if(!url){console.warn("Failed to fetch recent Sea Pen image data",path)}store.dispatch(seaPenAction.setRecentSeaPenImageDataAction({path:path},{url:url,queryInfo:queryInfo}))})))}}export function openFeedbackDialog(metadata,provider){provider.openFeedbackDialog(metadata)}export async function getShouldShowSeaPenTermsOfServiceDialog(provider,store){const{shouldShowDialog:shouldShowDialog}=await provider.shouldShowSeaPenTermsOfServiceDialog();store.dispatch(seaPenAction.setShouldShowSeaPenTermsOfServiceDialogAction(shouldShowDialog))}export async function acceptSeaPenTermsOfService(provider,store){if(!store.data.shouldShowSeaPenTermsOfServiceDialog){return}await provider.handleSeaPenTermsOfServiceAccepted();store.dispatch(seaPenAction.setShouldShowSeaPenTermsOfServiceDialogAction(false))}